// ─── File: GcTypesDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.gctypes;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class GcTypesDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        GcClassifier classifier = new GcClassifier();
        classifier.printActiveCollectors();
        classifier.report("startup");

        // LONG-LIVED: a retained list drives Old-gen occupancy over time.
        List<LedgerEntry> retained = new ArrayList<>();

        for (int round = 0; round < 50; round++) {
            // SHORT-LIVED churn → frequent, cheap Minor/Young GCs.
            for (int i = 0; i < 200_000; i++) {
                LedgerEntry tmp = new LedgerEntry("TXN-" + i, new byte[256]);
                if (tmp.sizeBytes() < 0) retained.add(tmp); // never true: tmp dies young
            }
            // Keep SOME entries each round → promotion → Old-gen collections eventually.
            retained.add(new LedgerEntry("KEEP-" + round, new byte[64 * 1024]));
        }

        classifier.report("after workload");
        log.info(() -> "retained long-lived entries = " + retained.size());
        log.info(() -> "Young collectors = cheap Minor GCs; Old/mixed = Major/Full equivalent");
    }
}

// ─── Would be in LedgerEntry.java (mixed lifetimes) ───
class LedgerEntry {
    private final String id;
    private final byte[] payload;
    LedgerEntry(String id, byte[] payload) { this.id = id; this.payload = payload; }
    int sizeBytes() { return payload.length; }
    String getId() { return id; }
}

// ─── Would be in GcClassifier.java (classifies collector beans) ───
class GcClassifier {
    private static final Logger log = Logger.getLogger("BankLog");

    void printActiveCollectors() {
        for (java.lang.management.GarbageCollectorMXBean gc :
                java.lang.management.ManagementFactory.getGarbageCollectorMXBeans()) {
            log.info(() -> "active collector: " + gc.getName());
        }
    }

    void report(String phase) {
        long youngCount = 0, youngMs = 0, oldCount = 0, oldMs = 0;
        for (java.lang.management.GarbageCollectorMXBean gc :
                java.lang.management.ManagementFactory.getGarbageCollectorMXBeans()) {
            String n = gc.getName();
            boolean young = n.contains("Young") || n.contains("Scavenge")
                    || n.contains("ParNew") || n.contains("Copy");
            if (young) { youngCount += gc.getCollectionCount(); youngMs += gc.getCollectionTime(); }
            else       { oldCount   += gc.getCollectionCount(); oldMs   += gc.getCollectionTime(); }
        }
        long yc = youngCount, ym = youngMs, oc = oldCount, om = oldMs;
        log.info(() -> "[" + phase + "] MINOR(young): count=" + yc + " time=" + ym + "ms | "
                + "MAJOR/FULL(old/mixed): count=" + oc + " time=" + om + "ms");
    }
}
